class Solution {
public:
    bool isTransformable(string s, string t) {
        int n = s.size();
        vector<int> pos[10];
        for (int i = 0; i < n; i++) {
            pos[s[i] - '0'].push_back(i);
        }
        int idx[10] = {};

        for (int i = 0; i < n; i++) {
            int c = t[i] - '0';
            if (idx[c] >= (int)pos[c].size()) return false;
            int p = pos[c][idx[c]];
            for (int d = 0; d < c; d++) {
                if (idx[d] < (int)pos[d].size() && pos[d][idx[d]] < p) {
                    return false;
                }
            }
            idx[c]++;
        }
        return true;
    }
};
